sql.if:
AND (
CAST(COALESCE(r.task_type, '') AS BINARY)CAST(COALESCE(r.source, '') AS BINARY)CAST(COALESCE(r.detail, '') AS BINARY)CAST(COALESCE(r.status_label, '') AS BINARY)CAST('' AS BINARY) <> CAST(COALESCE(#{after.taskType}, '') AS BINARY)CAST(COALESCE(#{after.source}, '') AS BINARY)CAST(COALESCE(#{after.detail}, '') AS BINARY)CAST(COALESCE(#{after.statusLabel}, '') AS BINARY)CAST('' AS BINARY) OR (CAST(COALESCE(r.task_type, '') AS BINARY)CAST(COALESCE(r.source, '') AS BINARY)CAST(COALESCE(r.detail, '') AS BINARY)CAST(COALESCE(r.status_label, '') AS BINARY)CAST('' AS BINARY) = CAST(COALESCE(#{after.taskType}, '') AS BINARY)CAST(COALESCE(#{after.source}, '') AS BINARY)CAST(COALESCE(#{after.detail}, '') AS BINARY)CAST(COALESCE(#{after.statusLabel}, '') AS BINARY)CAST('' AS BINARY) AND 
((r.due_group > CASE WHEN #{after.dueAt} IS NULL THEN 1 ELSE 0 END) OR (r.due_group = CASE WHEN #{after.dueAt} IS NULL THEN 1 ELSE 0 END AND r.due_sort > COALESCE(#{after.dueAt}, CAST('1970-01-01 00:00:00' AS DATETIME))) OR (r.due_group = CASE WHEN #{after.dueAt} IS NULL THEN 1 ELSE 0 END AND r.due_sort = COALESCE(#{after.dueAt}, CAST('1970-01-01 00:00:00' AS DATETIME)) AND r.created_sort < CASE WHEN #{after.dueAt} IS NULL THEN COALESCE(#{after.createdAt}, CAST('1970-01-01 00:00:00' AS DATETIME)) ELSE CAST('1970-01-01 00:00:00' AS DATETIME) END) OR (r.due_group = CASE WHEN #{after.dueAt} IS NULL THEN 1 ELSE 0 END AND r.due_sort = COALESCE(#{after.dueAt}, CAST('1970-01-01 00:00:00' AS DATETIME)) AND r.created_sort = CASE WHEN #{after.dueAt} IS NULL THEN COALESCE(#{after.createdAt}, CAST('1970-01-01 00:00:00' AS DATETIME)) ELSE CAST('1970-01-01 00:00:00' AS DATETIME) END AND r.numeric_id < #{after.numericId}))
)
)
